+@lru_cache(maxsize=256)
+def _bicubic_coeffs(in_size: int, out_size: int) -> tuple[mx.array, mx.array, int]:
+    """Pillow ``_precompute_coeffs`` for ``Image.BICUBIC`` in 22-bit fixed point."""
+    scale = in_size / out_size
