+    ks = np.arange(ksize)[None, :]
+    x_arg = (ks + xmin[:, None] - centers[:, None] + 0.5) / filterscale
+    w = _cubic_filter(x_arg)
+    w = np.where(ks < xmax[:, None], w, 0.0)
